  test('1. Container has role status', () => {
    render(<ScreenReaderStatusMessage message="Test" />);
    const container = screen.getByRole('status');
    expect(container).toBeInTheDocument();
  });

  test('2. Message is inside container', () => {
    render(<ScreenReaderStatusMessage message="13 search results found" />);
    const container = screen.getByRole('status');
    expect(container.textContent).toBe('13 search results found');
  });

  test('3. Equivalent information resides in container', () => {
    const msg = <img alt="Shopping cart with 1 item" src="cart.png" />;
    render(<ScreenReaderStatusMessage message={msg} />);
    const container = screen.getByRole('status');
    expect(container.querySelector('img')).toBeInTheDocument();
  });

  test('4. Visible functionality hides duplicate from accessibility tree', () => {
    render(<ScreenReaderStatusMessage message="Visible text" visible={true} />);
    const visibleDiv = screen.getByText('Visible text');
    expect(visibleDiv.getAttribute('aria-hidden')).toBe('true');
  });
});
